<script setup>
import { computed } from 'vue';

const props = defineProps({ simulation: Object, message: String, role: String, buttonPermissionIds: { type: Array, default: () => [] } });
defineEmits(['run', 'decide', 'fault', 'reset']);
const canRun = computed(() => props.simulation?.canControl && props.buttonPermissionIds.includes('simulation.run'));
const canDecide = computed(() => props.buttonPermissionIds.includes('simulation.approval.decide'));
const canManageFault = computed(() => props.simulation?.canControl && props.buttonPermissionIds.includes('simulation.fault.manage'));
const canReset = computed(() => props.simulation?.canControl && props.buttonPermissionIds.includes('simulation.reset'));
const pendingApprovals = computed(() => (props.simulation?.approvals || []).filter((item) => item.status === 'pending'));
const recentEvents = computed(() => props.simulation?.runtimeEvents || []);
const recentAudit = computed(() => props.simulation?.audit || []);
const semanticRuns = computed(() => (props.simulation?.activeRuns || []).filter((item) => item.semanticValidation));
</script>

<template>
  <section v-if="simulation" class="panel simulation-center">
    <div class="section-header"><div><span class="eyebrow">STATEFUL MOCK PROCESS CENTER</span><h2>模拟运行中心</h2><p>以真实系统接口契约模拟事件、审批、状态写回与审计。所有操作仅影响当前 API 进程的运行时数据。</p></div><div class="simulation-status"><b>{{ simulation.runtimeEventCount }}</b><small>运行时事件</small></div></div>
    <div class="simulation-flow"><span>模拟 Connector</span><i>→</i><span>事件流</span><i>→</i><span>Semantica 入图校验</span><i>→</i><span>Agent 证据</span><i>→</i><span>OA 审批</span><i>→</i><span>审批后复校验</span></div>
    <div class="scenario-grid"><article v-for="scenario in simulation.scenarios" :key="scenario.id"><div><span>{{ scenario.id }}</span><b>{{ scenario.name }}</b></div><p>{{ scenario.description }}</p><small>业务标识：{{ scenario.businessKey }} · {{ scenario.systems.join(' / ').toUpperCase() }}</small><button :disabled="!canRun" @click="$emit('run', scenario.id)">启动演练</button></article></div>
    <div class="simulation-workspace"><section><div class="simulation-subhead"><b>模拟 OA 审批</b><span>{{ pendingApprovals.length }} 项待处理</span></div><article v-for="approval in pendingApprovals" :key="approval.id" class="approval-row"><div><b>{{ approval.title }}</b><small>{{ approval.subject }} · {{ approval.detail }}</small></div><div v-if="canDecide && approval.approverRoles.includes(role)" class="approval-actions"><button class="approve" @click="$emit('decide', { id: approval.id, decision: 'approved' })">批准</button><button class="reject" @click="$emit('decide', { id: approval.id, decision: 'rejected' })">驳回</button></div><em v-else>待 {{ approval.approverRoles.join(' / ') }} 处理或按钮权限授权</em></article><p v-if="!pendingApprovals.length" class="empty-state">尚无待处理的模拟审批。启动一个场景后将在此生成 OA 待办。</p></section><section><div class="simulation-subhead"><b>运行时事件流</b><span>最新 {{ recentEvents.length }} 条</span></div><article v-for="event in recentEvents" :key="event.id" class="event-row"><i :class="event.system.toLowerCase()"></i><div><b>{{ event.system }} · {{ event.eventType }}</b><small>{{ event.id }} · {{ event.status }} · {{ event.payload.materialBatchId || event.payload.batchId || event.payload.orderId || event.payload.equipmentId }}</small></div></article><p v-if="!recentEvents.length" class="empty-state">当前为基础种子数据状态；启动场景以生成可推进的运行时事件。</p></section></div>
    <section v-if="semanticRuns.length" class="simulation-workspace semantic-workspace"><div class="simulation-subhead"><b>Semantica 验证结果</b><span>仅合成 Demo 事实入图</span></div><article v-for="run in semanticRuns" :key="run.id" class="audit-row"><div><b>{{ run.scenarioName }} · {{ run.semanticValidation.status === 'verified' ? '已验证' : '未验证' }}</b><small>{{ run.semanticValidation.status === 'verified' ? `事实 ${run.semanticValidation.run?.facts || 0} 条 · 系统 ${(run.semanticValidation.run?.systems || []).join(' / ')} · 溯源校验通过` : run.semanticValidation.detail || '本机 Semantica 服务不可用，Agent 继续使用受控本地投影。' }}</small></div><time>{{ run.semanticValidation.checkedAt ? new Date(run.semanticValidation.checkedAt).toLocaleTimeString() : '-' }}</time></article></section>
    <div class="simulation-workspace connector-workspace"><section><div class="simulation-subhead"><b>Mock Connector 健康与故障注入</b><span>需管理员与按钮权限共同授权</span></div><article v-for="connector in simulation.connectors" :key="connector.systemId" class="connector-row"><div><b>{{ connector.systemId.toUpperCase() }} · {{ connector.adapter }}</b><small>{{ connector.statusMessage }}</small></div><div class="connector-control"><em :class="`health-${connector.health}`">{{ connector.faultName }}</em><select :value="connector.faultId" :disabled="!canManageFault" @change="$emit('fault', { systemId: connector.systemId, faultId: $event.target.value })"><option v-for="fault in simulation.faultCatalog" :key="fault.id" :value="fault.id">{{ fault.name }}</option></select></div></article></section><section><div class="simulation-subhead"><b>流程审计回放</b><span>最新 {{ recentAudit.length }} 条</span></div><article v-for="item in recentAudit" :key="item.id" class="audit-row"><div><b>{{ item.action }}</b><small>{{ item.detail }}</small></div><time>{{ item.at ? new Date(item.at).toLocaleTimeString() : '-' }}</time></article><p v-if="!recentAudit.length" class="empty-state">运行场景、审批、故障注入及重置操作将在此留下模拟审计轨迹。</p></section></div>
    <div class="simulation-footer"><p>Mock Connector：{{ simulation.connectors.map((item) => item.adapter).join('、') }}。{{ simulation.policy }}</p><button v-if="canReset" class="reset" @click="$emit('reset')">重置模拟运行时</button></div><p v-if="message" class="simulation-message">{{ message }}</p>
  </section>
</template>
